-- Unions in the generated schema need explicit stable-ID checks at the database boundary.
create function mathin_internal.valid_miniapp_native_composition(v jsonb) returns boolean
language plpgsql immutable set search_path=public,pg_temp as $composition$
declare screens jsonb; screen jsonb; modules jsonb;
begin
  if v is null then return true; end if;
  screens:=coalesce(v->'screens','[]'::jsonb);
  if jsonb_typeof(screens)<>'array' then return false; end if;
  if jsonb_array_length(screens)<>(select count(distinct s->>'id') from jsonb_array_elements(screens) s) then return false; end if;
  for screen in select * from jsonb_array_elements(screens) loop
    modules:=screen->'modules';
    if jsonb_typeof(modules) is distinct from 'array' then return false; end if;
    if jsonb_array_length(modules)<>(select count(distinct m->>'id') from jsonb_array_elements(modules) m) then return false; end if;
  end loop;
  if exists(select 1 from jsonb_array_elements(v->'pages') p cross join lateral jsonb_array_elements(p->'blocks') b
    where p->>'purpose'='report' and b->>'kind'='accountRecords') then return false; end if;
  return true;
exception when others then return false;
end $composition$;

create or replace function mathin_internal.valid_miniapp_settings(p jsonb) returns boolean
language sql immutable security definer set search_path=public,pg_temp as $validation$
  select coalesce(mathin_internal.valid_miniapp_settings_before_experience(p-'experience') and octet_length(p::text)<=1126400
    and (not(p ? 'experience') or (mathin_internal.experience_schema_valid(p->'experience',mathin_internal.miniapp_experience_schema())
      and mathin_internal.valid_miniapp_native_composition(p->'experience'))),false);
$validation$;

-- The original entry validator and current clients share these additional personal-record destinations.
do $actions$
declare definition text; previous text := $list$'privacy','document','page','offering','catalog','form','web'$list$;
begin
  definition:=pg_get_functiondef('mathin_internal.valid_miniapp_presentation_settings(jsonb)'::regprocedure);
  if position(previous in definition)=0 then raise exception 'MINIAPP_ACTION_VALIDATOR_CHANGED'; end if;
  execute replace(definition,previous,previous||$more$,'reservations','serviceRequests','serviceBookings','notifications'$more$);
end $actions$;
revoke all on function mathin_internal.valid_miniapp_native_composition(jsonb) from public,anon,authenticated;
notify pgrst,'reload schema';
commit;
